import {renderFunnel,layoutGraph,edgeFadeStops} from './lab-engine.js';
import {validateData} from '../atlas-kit.js';
import {INK,PAPER,element,screenSwatch,screenLabels,screenTypes} from './screens.js';
import {variants,createConfig,parseConfig,sampleData} from './config.js';
const $=s=>document.querySelector(s),format=n=>new Intl.NumberFormat('en-US').format(n),percent=(v,d)=>d?`${(100*v/d).toFixed(1)}%`:'—';
const state=Object.fromEntries(variants.map(v=>[v,createConfig(v)]));let variant='continuous',view='config',svg=null,pinned=null,saved=[];const storageKey='atlas-funnel-lab-configs-v1';
try{const raw=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(raw))saved=raw.flatMap(item=>{try{return typeof item.name==='string'?[{...item,config:parseConfig(item.config)}]:[];}catch{return [];}});}catch{$('.storage-note').textContent='Browser storage unavailable. Export JSON to keep a portable copy.';}
const titles={continuous:'Continuous funnel',vertical:'Vertical funnel',branching:'Branching funnel'},captions={continuous:'01 / Cohort progression · height encodes quantity',vertical:'02 / Stage comparison · width encodes quantity',branching:'03 / Connected buckets · every split distributes 100%'};
const shared=[['density','Screen pitch',3,14,1,'px'],['strokeWidth','Outline weight',.25,.75,.05,'pt'],['patternAngle','Hatch angle',-90,90,5,'°'],['dotGain','Dot gain',-.8,.2,.01,'%'],['roughness','Edge irregularity',0,.6,.05,'px'],['fontSize','Label size',12,18,1,'px']];
const shapes={continuous:[['curve','Curvature',.1,.8,.05,''],['chartHeight','Funnel height',120,265,5,'px'],['edgeFade','Edge fade',0,.45,.05,'%']],vertical:[['stageHeight','Funnel height',250,330,5,'px'],['stageGap','Stage gap',0,20,1,'px'],['capCurve','Cap curvature',0,20,1,'px'],['borderRadius','Border radius',0,20,1,'px'],['tailRatio','Terminal taper',.15,1,.05,'%']],branching:[['curve','Curvature',.1,.8,.05,''],['nodeGap','Branch spacing',28,85,1,'px'],['nodeWidth','Node width',1,6,.5,'px']]};
function updateFadePreview(preview,fade){preview.style.maskImage=fade?`linear-gradient(to right, ${edgeFadeStops(fade).map(([offset,alpha])=>`rgb(0 0 0 / ${alpha}) ${Math.round(offset*1000)/10}%`).join(', ')})`:'none';}
const display=(v,u)=>u==='%'?`${Math.round(v*100)}%`:u==='°'?`${v}°`:u==='px'?`${Number(v.toFixed(2))} px`:u==='pt'?`${v.toFixed(2)} pt`:v.toFixed(2);
function controls(){const holder=$('#controls');holder.replaceChildren();const options=state[variant].options,texture=document.createElement('div');texture.className='texture-grid';texture.setAttribute('role','group');texture.setAttribute('aria-label','Screen sequence');for(const[key,label]of [['mixed','Atlas mix'],...screenTypes.map(type=>[type,screenLabels[type]])]){const b=document.createElement('button');b.dataset.texture=key;b.setAttribute('aria-pressed',String(options.texture===key));const swatch=screenSwatch(key,{...options,seed:state[variant].seed},`control-${key}`);b.append(swatch,document.createTextNode(label));b.addEventListener('click',()=>{options.texture=key;texture.querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));render();});texture.append(b);}holder.append(texture);
for(const[name,rows]of [['Ink & screen',shared],['Geometry',shapes[variant]]]){const field=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=name;field.append(legend);for(const[key,label,min,max,step,unit]of rows){const div=document.createElement('div');div.className=key==='edgeFade'?'control control--fade':'control';const lbl=document.createElement('label');lbl.className='control-label';lbl.htmlFor=key;lbl.append(document.createTextNode(label));const output=document.createElement('output');output.htmlFor=key;output.textContent=display(options[key],unit);lbl.append(output);const input=document.createElement('input');input.type='range';input.id=key;input.min=min;input.max=max;input.step=step;input.value=options[key];let preview;if(key==='edgeFade'){preview=document.createElement('div');preview.className='fade-preview';preview.setAttribute('aria-hidden','true');updateFadePreview(preview,options[key]);}input.addEventListener('input',()=>{options[key]=Number(input.value);output.textContent=display(options[key],unit);if(preview)updateFadePreview(preview,options[key]);render();});div.append(lbl,input);if(preview){const hint=document.createElement('small');hint.className='fade-hint';hint.textContent='First and last ribbon only';div.append(preview,hint);}field.append(div);}holder.append(field);}
for(const[key,label]of (variant==='vertical'?[['labels','Direct annotations'],['paperGrain','Paper grain']]:[['labels','Direct annotations'],['guides','Stage guides'],['paperGrain','Paper grain']])){const l=document.createElement('label');l.className='toggle';l.htmlFor=key;l.textContent=label;const input=document.createElement('input');input.type='checkbox';input.id=key;input.checked=options[key];input.addEventListener('change',()=>{options[key]=input.checked;render();});l.append(input);holder.append(l);}$('#seed').value=state[variant].seed;}
const paths=()=>svg?[...svg.querySelectorAll('[data-key]')]:[];
function highlight(info){svg.atlasClearPull?.();svg.atlasHighlightedKey=info?.key??null;const keys=new Set();if(info?.kind==='link'&&svg.atlasLayout){const links=svg.atlasLayout.links;const traverse=(id,up,seen=new Set())=>{if(seen.has(id))return;seen.add(id);links.filter(l=>up?l.target===id:l.source===id).forEach(l=>{keys.add(l.id);traverse(up?l.source:l.target,up,seen);});};const link=links.find(l=>l.source===info.source&&l.target===info.target);if(link)keys.add(link.id);traverse(info.source,true);traverse(info.target,false);}paths().forEach(p=>{const active=!info||(info.kind==='link'?keys.has(p.dataset.key):p.atlasInfo.key===info.key);p.setAttribute('fill',active?p.getAttribute('data-base-fill'):PAPER);if(active)p.removeAttribute('stroke-dasharray');else p.setAttribute('stroke-dasharray','2 4');p.setAttribute('aria-pressed',String(pinned?.key===p.atlasInfo.key));p.atlasEmphasis.setAttribute('data-emphasis',String(Boolean(info)&&active));});}
function inspect(info){$('#inspect-state').textContent=pinned?'PINNED PATH':'PATH INSPECTOR';$('#inspect-path').textContent=info?.label||'Explore a ribbon';$('#inspect-value').textContent=info?format(info.value):'—';$('#inspect-conversion').textContent=info?percent(info.value,info.denominator):'—';$('#inspect-total').textContent=info?percent(info.value,info.total):'—';$('#unpin').hidden=!pinned;}
function select(info){pinned=pinned?.key===info?.key?null:info;highlight(pinned);inspect(pinned||info);}
function attachProximity(svg,sections,axis){
 const radius=24;
 const contours=sections.map(path=>{const length=path.getTotalLength(),count=Math.ceil(length/12);return {path,bounds:path.getBBox(),points:Array.from({length:count+1},(_,i)=>path.getPointAtLength(length*i/count))};});
 let pulled=null;
 svg.atlasClearPull=()=>{if(!pulled)return;pulled.style.removeProperty('--pull-x');pulled.style.removeProperty('--pull-y');pulled=null;};
 const show=info=>{if(svg.atlasHighlightedKey===(info?.key??null))return;highlight(info);if(info)inspect(info);};
 svg.addEventListener('pointermove',e=>{
  if(e.pointerType!=='mouse'||!matchMedia('(hover: hover) and (pointer: fine)').matches||pinned)return;
  $('#canvas').dataset.motion='pointer';
  const section=e.target.closest('path[data-key]');
  if(section){svg.atlasClearPull();show(section.atlasInfo);return;}
  const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;
  const cursor=point.matrixTransform(svg.getScreenCTM().inverse());
  let nearest=null;
  for(const {path,bounds,points} of contours){
   if(cursor.x<bounds.x-radius||cursor.x>bounds.x+bounds.width+radius||cursor.y<bounds.y-radius||cursor.y>bounds.y+bounds.height+radius)continue;
   for(let i=1;i<points.length;i++){
    const a=points[i-1],b=points[i],vx=b.x-a.x,vy=b.y-a.y,length=vx*vx+vy*vy;
    if(!length)continue;
    const t=Math.max(0,Math.min(1,((cursor.x-a.x)*vx+(cursor.y-a.y)*vy)/length));
    const dx=cursor.x-a.x-t*vx,dy=cursor.y-a.y-t*vy,distance=dx*dx+dy*dy;
    if(axis==='x'?Math.abs(dx)<=Math.abs(dy):Math.abs(dy)<=Math.abs(dx))continue;
    if(!nearest||distance<nearest.distance)nearest={path,dx,dy,distance};
   }
  }
  if(!nearest||nearest.distance>=radius*radius){show(null);return;}
  show(nearest.path.atlasInfo);
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){svg.atlasClearPull();return;}
  const distance=Math.sqrt(nearest.distance),offset=axis==='x'?nearest.dx:nearest.dy;
  const pull=Math.sign(offset)*Math.min(5,Math.abs(offset)*2)*(1-distance/radius);
  const emphasis=nearest.path.atlasEmphasis;
  if(pulled&&pulled!==emphasis)svg.atlasClearPull();
  emphasis.style.setProperty('--pull-x',`${axis==='x'?pull:0}px`);
  emphasis.style.setProperty('--pull-y',`${axis==='y'?pull:0}px`);
  pulled=emphasis;
 });
 svg.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'){highlight(pinned);if(pinned)inspect(pinned);}});
}
function render(){const config=state[variant];try{const next=renderFunnel(config.data,{...config.options,variant,idPrefix:'lab-figure',seed:config.seed});$('#canvas').replaceChildren(next);svg=next;$('#figure-error').hidden=true;$('#svg-export').disabled=false;$('#save').disabled=false;}catch(e){$('#figure-error').textContent=e.message;$('#figure-error').hidden=false;$('#svg-export').disabled=true;$('#save').disabled=true;return;}pinned=paths().find(p=>p.atlasInfo.key===pinned?.key)?.atlasInfo||null;$('#canvas').dataset.motion='instant';paths().forEach(p=>{
 const emphasis=element('path',{d:p.getAttribute('d'),fill:'none',stroke:INK,'stroke-width':1,'vector-effect':'non-scaling-stroke',opacity:0,class:'section-emphasis','aria-hidden':'true','pointer-events':'none','data-emphasis':'false'});if(p.hasAttribute('mask'))emphasis.setAttribute('mask',p.getAttribute('mask'));p.atlasEmphasis=emphasis;svg.append(emphasis);
 const preview=()=>{if(!pinned){highlight(p.atlasInfo);inspect(p.atlasInfo);}};
 p.addEventListener('pointerenter',e=>{if(e.pointerType!=='mouse'||!matchMedia('(hover: hover) and (pointer: fine)').matches)return;$('#canvas').dataset.motion='pointer';preview();});
 p.addEventListener('focus',()=>{$('#canvas').dataset.motion='instant';preview();});
 p.addEventListener('blur',()=>{$('#canvas').dataset.motion='instant';highlight(pinned);});
 p.addEventListener('pointerdown',e=>{$('#canvas').dataset.motion=e.pointerType==='mouse'?'pointer':'instant';});
 p.addEventListener('click',()=>select(p.atlasInfo));
 p.addEventListener('keydown',e=>{$('#canvas').dataset.motion='instant';if(e.key==='Enter'||e.key===' '){e.preventDefault();select(p.atlasInfo);}if(e.key==='Escape'){pinned=null;highlight(null);inspect(p.atlasInfo);}});
 });
 attachProximity(svg,paths(),variant==='vertical'?'y':'x');
 highlight(pinned);inspect(pinned||paths()[0]?.atlasInfo);$('.figure-subtitle').textContent=variant==='branching'?'One entry bucket. Every split distributes 100% to its children.':'A study of quantity, progression, and loss.';$('#figure-title').textContent=titles[variant];$('#figure-number').textContent=`FIG. 00${variants.indexOf(variant)+1}`;$('#figure-caption').textContent=captions[variant];document.querySelectorAll('[data-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===variant)));$('#config-code').textContent=JSON.stringify(config,null,2);$('#compare-view p').textContent=variant==='branching'?'Conversion uses the parent bucket quantity. Every split accounts for 100%, including drop-off.':'Conversion uses the preceding stage quantity. Of total uses the entry quantity.';comparison();legend();}

function legend(){const holder=$('#screen-legend');holder.replaceChildren();const names=['sparse','dense','am','hatch','cross','coarse','solid'];for(const type of names){const item=document.createElement('div');item.className='legend-item';item.append(screenSwatch(type,{...state[variant].options,seed:state[variant].seed},`legend-${type}`));const label=document.createElement('span');label.textContent=screenLabels[type];const caption=document.createElement('small');caption.textContent=type==='am'?'30% SCREEN':type==='cross'||type==='hatch'?'50% SCREEN':type==='coarse'?'70% SCREEN':type==='solid'?'SMALL MARKS ONLY':'STOCHASTIC';label.append(caption);item.append(label);holder.append(item);}}

function comparison(){const body=$('#rows');body.replaceChildren();paths().forEach(p=>{const info=p.atlasInfo,row=document.createElement('tr'),first=document.createElement('td'),button=document.createElement('button');button.textContent=info.label;button.addEventListener('click',()=>{$('#canvas').dataset.motion='instant';select(info);});first.append(button);row.append(first);for(const text of [format(info.value),percent(info.value,info.denominator),percent(info.value,info.total)]){const td=document.createElement('td');td.textContent=text;row.append(td);}body.append(row);});}
function setView(value){view=value;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));for(const key of ['config','data','compare'])$('#'+key+'-view').hidden=key!==view;$('#copy').hidden=view==='compare';$('#copy').textContent=view==='data'?'Copy data':'Copy JSON';if(view==='data')$('#data').value=JSON.stringify(state[variant].data,null,2);}
function switchVariant(value){variant=value;pinned=null;controls();render();if(view==='data')$('#data').value=JSON.stringify(state[variant].data,null,2);$('#data-error').textContent='';}
function notice(message){$('#status').textContent=message;$('#status').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#status').hidden=true,3500);}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function shelf(){const holder=$('#saved-list');holder.replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='empty';p.textContent='Save a configuration to compare and return to it.';holder.append(p);return;}for(const item of saved){const button=document.createElement('button');button.className='saved-card';const label=document.createElement('strong');label.textContent=item.name;const mode=document.createElement('span');mode.textContent=titles[item.config.variant];const detail=document.createElement('span');detail.textContent=`${item.config.options.texture} / seed ${item.config.seed}`;button.append(label,mode,detail);button.addEventListener('click',()=>{const config=parseConfig(item.config);state[config.variant]=config;switchVariant(config.variant);$('#config-name').value=item.name;notice(`Restored ${item.name}`);});holder.append(button);}}
function sample(seed){state[variant].seed=seed;state[variant].data=sampleData(variant,seed);state[variant].dataOrigin='seed';pinned=null;render();$('#seed').value=seed;if(view==='data')$('#data').value=JSON.stringify(state[variant].data,null,2);$('#data-error').textContent='';}
document.querySelectorAll('[data-variant]').forEach(b=>b.addEventListener('click',()=>switchVariant(b.dataset.variant)));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#reset').addEventListener('click',()=>{state[variant]=createConfig(variant);switchVariant(variant);notice('Variant reset');});$('#seed').addEventListener('change',()=>{const n=Number($('#seed').value);if(!Number.isInteger(n)||n<0||n>4294967295){notice('Use a seed between 0 and 4294967295');$('#seed').value=state[variant].seed;return;}sample(n);});$('#generate').addEventListener('click',()=>sample(crypto.getRandomValues(new Uint32Array(1))[0]));$('#restore-data').addEventListener('click',()=>sample(state[variant].seed));$('#apply-data').addEventListener('click',()=>{try{const data=JSON.parse($('#data').value);validateData(data,variant);if(variant==='branching')layoutGraph(data,state[variant].options);state[variant].data=data;state[variant].dataOrigin='custom';pinned=null;render();$('#data-error').textContent='';notice('Data applied');}catch(e){$('#data-error').textContent=e.message;}});$('#unpin').addEventListener('click',()=>{pinned=null;highlight(null);inspect(paths()[0]?.atlasInfo);});
$('#save').addEventListener('click',()=>{const config=parseConfig(state[variant]),name=$('#config-name').value.trim()||`${titles[variant]} ${saved.length+1}`;saved.unshift({name,config});shelf();try{localStorage.setItem(storageKey,JSON.stringify(saved));notice(`Saved ${name}`);}catch{notice('Saved for this session. Export JSON to keep it.');$('.storage-note').textContent='Browser storage unavailable. Export JSON to keep a portable copy.';}});$('#download').addEventListener('click',()=>download(JSON.stringify(state[variant],null,2),`atlas-lab-${variant}-${state[variant].seed}.json`,'application/json'));$('#svg-export').addEventListener('click',()=>{const config=state[variant];const clone=renderFunnel(config.data,{...config.options,variant,idPrefix:'lab-export',seed:config.seed,stippleScale:3});clone.querySelectorAll('[data-key]').forEach(p=>{p.removeAttribute('tabindex');p.removeAttribute('role');p.removeAttribute('aria-pressed');p.setAttribute('fill',p.getAttribute('data-base-fill'));p.removeAttribute('stroke-dasharray');p.removeAttribute('data-base-fill');});clone.setAttribute('width',clone.getAttribute('viewBox').split(' ')[2]);clone.setAttribute('height',clone.getAttribute('viewBox').split(' ')[3]);download(new XMLSerializer().serializeToString(clone),`atlas-lab-${variant}.svg`,'image/svg+xml');});$('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(view==='data'?$('#data').value:JSON.stringify(state[variant],null,2));notice('JSON copied');}catch{notice('Copy unavailable. Use Export config to download JSON.');}});
$('#import').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async()=>{const file=$('#import-file').files[0];if(!file)return;try{if(file.size>1000000)throw new Error('Choose a configuration smaller than 1 MB.');const config=parseConfig(JSON.parse(await file.text()));state[config.variant]=config;switchVariant(config.variant);notice('Configuration imported');}catch(e){notice(e.message);}finally{$('#import-file').value='';}});controls();render();shelf();
